CREATE TABLE actors (id TEXT PRIMARY KEY, issuer TEXT NOT NULL, subject TEXT NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('human','agent')), system_admin INTEGER NOT NULL DEFAULT 0 CHECK(system_admin IN (0,1)), UNIQUE(issuer,subject));
CREATE TABLE projects (id TEXT PRIMARY KEY, key TEXT UNIQUE NOT NULL, name TEXT NOT NULL, instructions TEXT NOT NULL DEFAULT '', policy TEXT NOT NULL CHECK(policy IN ('self','independent','human')), revision INTEGER NOT NULL CHECK(revision>0), ticket_seq INTEGER NOT NULL DEFAULT 0, event_seq INTEGER NOT NULL DEFAULT 0 CHECK(event_seq BETWEEN 0 AND 9007199254740991), created_at TEXT NOT NULL, execution_hints TEXT CHECK(execution_hints IS NULL OR (json_valid(execution_hints) AND json_type(execution_hints)='object')));
CREATE TABLE members (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), actor_id TEXT NOT NULL REFERENCES actors(id), role TEXT NOT NULL CHECK(role IN ('reader','contributor','verifier','admin')), UNIQUE(project_id,actor_id));
CREATE TABLE tickets (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), key TEXT UNIQUE NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('backlog','ready','in_progress','in_review','done','cancelled')), priority INTEGER NOT NULL CHECK(priority BETWEEN 1 AND 5), labels TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(labels) AND json_type(labels)='array'), capabilities TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(capabilities) AND json_type(capabilities)='array'), assignee_id TEXT REFERENCES actors(id), parent_id TEXT REFERENCES tickets(id), revision INTEGER NOT NULL CHECK(revision>0), requirements_revision INTEGER NOT NULL CHECK(requirements_revision>0), created_by TEXT NOT NULL REFERENCES actors(id), approved_submission_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, execution_hints TEXT CHECK(execution_hints IS NULL OR (json_valid(execution_hints) AND json_type(execution_hints)='object')), UNIQUE(project_id,id));
CREATE INDEX tickets_queue ON tickets(project_id,status,priority,created_at,id);
CREATE INDEX tickets_parent ON tickets(project_id,parent_id);
CREATE TABLE criteria (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, ticket_id TEXT NOT NULL, text TEXT NOT NULL, position INTEGER NOT NULL, FOREIGN KEY(project_id,ticket_id) REFERENCES tickets(project_id,id));
CREATE INDEX criteria_ticket ON criteria(project_id,ticket_id,position);
CREATE TABLE links (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, source_id TEXT NOT NULL, target_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('blocks','related')), CHECK(source_id<>target_id), FOREIGN KEY(project_id,source_id) REFERENCES tickets(project_id,id), FOREIGN KEY(project_id,target_id) REFERENCES tickets(project_id,id), UNIQUE(source_id,target_id,kind));
CREATE INDEX links_target ON links(project_id,target_id,kind);
CREATE TABLE notes (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, ticket_id TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES actors(id), kind TEXT NOT NULL CHECK(kind IN ('comment','checkpoint','question','answer')), body TEXT NOT NULL, blocking INTEGER NOT NULL DEFAULT 0 CHECK(blocking IN (0,1)), answer_to TEXT REFERENCES notes(id), metadata TEXT NOT NULL CHECK(json_valid(metadata)), ticket_revision INTEGER NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(project_id,ticket_id) REFERENCES tickets(project_id,id));
CREATE INDEX notes_ticket_revision ON notes(project_id,ticket_id,ticket_revision DESC,id DESC);
CREATE INDEX notes_answers ON notes(answer_to) WHERE kind='answer';
CREATE INDEX notes_questions ON notes(project_id,ticket_id,blocking,created_at,id) WHERE kind='question';
CREATE TABLE claims (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, ticket_id TEXT UNIQUE NOT NULL, actor_id TEXT NOT NULL REFERENCES actors(id), token TEXT NOT NULL, expires_at TEXT NOT NULL, FOREIGN KEY(project_id,ticket_id) REFERENCES tickets(project_id,id));
CREATE TABLE submissions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, ticket_id TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES actors(id), requirements_revision INTEGER NOT NULL, evidence TEXT NOT NULL CHECK(json_valid(evidence)), summary TEXT NOT NULL, requirements_snapshot TEXT CHECK(requirements_snapshot IS NULL OR json_valid(requirements_snapshot)), ticket_revision INTEGER NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(project_id,ticket_id) REFERENCES tickets(project_id,id));
CREATE INDEX submissions_ticket_revision ON submissions(project_id,ticket_id,ticket_revision DESC,id DESC);
CREATE TABLE reviews (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, ticket_id TEXT NOT NULL, submission_id TEXT NOT NULL REFERENCES submissions(id), actor_id TEXT NOT NULL REFERENCES actors(id), decision TEXT NOT NULL CHECK(decision IN ('approve','request_changes')), feedback TEXT NOT NULL, ticket_revision INTEGER NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(project_id,ticket_id) REFERENCES tickets(project_id,id));
CREATE INDEX reviews_ticket_revision ON reviews(project_id,ticket_id,ticket_revision DESC,id DESC);
CREATE TABLE knowledge (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, body TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('policy','decision','runbook','architecture','note')), revision INTEGER NOT NULL CHECK(revision>0), archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), actor_id TEXT NOT NULL REFERENCES actors(id), updated_at TEXT NOT NULL);
CREATE INDEX knowledge_project ON knowledge(project_id,archived,id);
CREATE TABLE events (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), seq INTEGER NOT NULL CHECK(seq BETWEEN 0 AND 9007199254740991), actor_id TEXT NOT NULL REFERENCES actors(id), type TEXT NOT NULL, entity_id TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, UNIQUE(project_id,seq));
CREATE TABLE receipts (id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id), actor_id TEXT NOT NULL REFERENCES actors(id), operation TEXT NOT NULL, input_hash TEXT NOT NULL, result TEXT NOT NULL CHECK(json_valid(result)), created_at TEXT NOT NULL);
CREATE TABLE jobs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), entity_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('ticket','knowledge','checkpoint')), revision INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts>=0), available_at TEXT NOT NULL, locked_until TEXT, lock_token TEXT, last_error TEXT);
CREATE INDEX jobs_available ON jobs(available_at,locked_until);
CREATE TABLE search_documents (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), kind TEXT NOT NULL CHECK(kind IN ('ticket','knowledge','checkpoint')), revision INTEGER NOT NULL, title TEXT NOT NULL, text TEXT NOT NULL, archived INTEGER NOT NULL CHECK(archived IN (0,1)));
CREATE INDEX search_project ON search_documents(project_id,archived);
CREATE VIRTUAL TABLE search_fts USING fts5(title,text,content='search_documents',content_rowid='rowid',tokenize='porter unicode61 remove_diacritics 2');
CREATE TRIGGER search_insert AFTER INSERT ON search_documents BEGIN INSERT INTO search_fts(rowid,title,text) VALUES(new.rowid,new.title,new.text); END;
CREATE TRIGGER search_delete AFTER DELETE ON search_documents BEGIN INSERT INTO search_fts(search_fts,rowid,title,text) VALUES('delete',old.rowid,old.title,old.text); END;
CREATE TRIGGER search_update AFTER UPDATE ON search_documents BEGIN INSERT INTO search_fts(search_fts,rowid,title,text) VALUES('delete',old.rowid,old.title,old.text); INSERT INTO search_fts(rowid,title,text) VALUES(new.rowid,new.title,new.text); END;
